export function variationOf(o){const variation=o.name.split(': ')[1];return variation?variation.split(', ').map(v=>variationNames[v]||v).join(' · '):'';}
export function titleOf(o){const family=o.name.split(':')[0];const title=families[family]||family;const variation=variationOf(o);return variation?`${title} · ${variation}`:title;}
export function descriptionOf(o){return descriptions[o.name.split(':')[0]]||'跟随棋谱观察双方的出子顺序、中心兵形与王的安全。点击任一步查看局面，再展开变招树，比较不同的后续走法。';}
export function searchable(o){return `${o.name} ${titleOf(o)} ${o.eco} ${o.pgn} ${o.moves.join(' ')} ${o.name.includes('Najdorf')?'纳杰多夫 纳甲沃夫 纳道夫 纳伊多夫':''}`.toLowerCase();}
export const featuredNames=['Italian Game: Giuoco Piano','Sicilian Defense','Ruy Lopez',"Queen's Gambit",'French Defense','Caro-Kann Defense','London System','English Opening',"King's Indian Defense",'Nimzo-Indian Defense','Slav Defense','Scotch Game','Grünfeld Defense','Catalan Opening','Petrov Defense','Pirc Defense','Scandinavian Defense','Réti Opening',"King's Gambit",'Dutch Defense','Vienna Game','Alekhine Defense','Four Knights Game','Modern Defense'];
export function selectFeatured(data){return featuredNames.map(name=>{const candidates=data.filter(o=>o.name===(name==='Petrov Defense'?"Petrov's Defense":name));if(!candidates.length)return null;return candidates.find(o=>o.moves.length>=4&&o.moves.length<=8)||candidates[0];}).filter(Boolean);}
